args.query:
let curlDl = DeviceProcess
| where FileName == 'curl' and CommandLine contains '/tmp/' and (CommandLine contains '-o /tmp/' or CommandLine contains '--output');
let shellRun = DeviceProcess
| where FileName in ('bash','sh') or InitiatingProcessFileName endswith '/curl';
curlDl | project-rename DownloadTime=Timestamp | as download | join kind=inner(shell) on $left.DeviceId == $right.DeviceId;
shell
